-- For this test we duckdb set execution to false
SET duckdb.force_execution = false;
SET duckdb.unsafe_allow_execution_inside_functions = true;
CREATE TABLE t(a int);
INSERT INTO t VALUES (1);

CREATE TEMP TABLE t_ddb(a int) USING duckdb;
INSERT INTO t_ddb VALUES (1);

BEGIN;
SELECT * FROM t_ddb;
INSERT INTO t_ddb VALUES (2);
SELECT * FROM t_ddb ORDER BY a;
ROLLBACK;

-- Executing many write commands is fine
BEGIN;
INSERT INTO t_ddb VALUES (2);
INSERT INTO t_ddb VALUES (3);
INSERT INTO t_ddb VALUES (4);
INSERT INTO t_ddb VALUES (5);
INSERT INTO t_ddb VALUES (6);
COMMIT;

SELECT * FROM t_ddb;

-- Writing to PG and DDB tables in the same transaction is not supported. We
-- fail early for simple DML (no matter the order).
BEGIN;
INSERT INTO t_ddb VALUES (2);
INSERT INTO t VALUES (2);
ROLLBACK;

BEGIN;
INSERT INTO t VALUES (2);
INSERT INTO t_ddb VALUES (2);
ROLLBACK;

-- Unless users explicitly opt-in
BEGIN;
SET LOCAL duckdb.unsafe_allow_mixed_transactions = true;
INSERT INTO t_ddb VALUES (4);
INSERT INTO t VALUES (4);
COMMIT;

BEGIN;
SET LOCAL duckdb.unsafe_allow_mixed_transactions = true;
INSERT INTO t VALUES (5);
INSERT INTO t_ddb VALUES (5);
COMMIT;

-- And for other writes that are not easy to detect, such as CREATE TABLE, we
-- fail on COMMIT.
BEGIN;
INSERT INTO t_ddb VALUES (2);
CREATE TABLE t2(a int);
COMMIT;

-- Savepoints in PG-only transactions should still work
BEGIN;
INSERT INTO t VALUES (2);
SAVEPOINT my_savepoint;
INSERT INTO t VALUES (3);
ROLLBACK TO SAVEPOINT my_savepoint;
COMMIT;

-- But savepoints are not allowed in DuckDB transactions
BEGIN;
INSERT INTO t_ddb VALUES (2);
SAVEPOINT my_savepoint;
ROLLBACK;;

-- Also not already started ones
BEGIN;
SAVEPOINT my_savepoint;
INSERT INTO t_ddb VALUES (2);
ROLLBACK;;

-- Unless the subtransaction is already completed
BEGIN;
SAVEPOINT my_savepoint;
SELECT count(*) FROM t;
RELEASE SAVEPOINT my_savepoint;
INSERT INTO t_ddb VALUES (2);
COMMIT;

-- Statements in functions should be run inside a single transaction. So a
-- failure later in the function should roll back.
CREATE OR REPLACE FUNCTION f(fail boolean) RETURNS void
    LANGUAGE plpgsql
    RETURNS NULL ON NULL INPUT
    AS
$$
BEGIN
INSERT INTO t_ddb VALUES (8);
IF fail THEN
    RAISE EXCEPTION 'fail';
END IF;
END;
$$;

-- After executing the function the table should not contain the value 8,
-- because that change was rolled back
SELECT * FROM f(true);
SELECT * FROM t_ddb ORDER BY a;

-- But if the function succeeds we should see the new value
SELECT * FROM f(false);
SELECT * FROM t_ddb ORDER BY a;

-- DuckDB DDL in transactions is allowed
BEGIN;
    CREATE TEMP TABLE t_ddb2(a int) USING duckdb;
    CREATE TEMP TABLE t_ddb3(a) USING duckdb AS SELECT 1;
    DROP TABLE t_ddb3;
    INSERT INTO t_ddb2 VALUES (1);
    ALTER TABLE t_ddb2 ADD COLUMN b int;
    ALTER TABLE t_ddb2 ADD COLUMN c int;
    ALTER TABLE t_ddb2 ADD COLUMN d int DEFAULT 100, ADD COLUMN e int DEFAULT 10;
    ALTER TABLE t_ddb2 RENAME COLUMN b TO f;
    ALTER TABLE t_ddb2 RENAME TO t_ddb4;
    SELECT * FROM t_ddb4;
END;

DROP TABLE t_ddb4;

-- Similarly is DDL in functions

CREATE OR REPLACE FUNCTION f2() RETURNS void
    LANGUAGE plpgsql
    RETURNS NULL ON NULL INPUT
    AS
$$
BEGIN
    CREATE TEMP TABLE t_ddb2(a int) USING duckdb;
    CREATE TEMP TABLE t_ddb3(a) USING duckdb AS SELECT 1;
    DROP TABLE t_ddb3;
    INSERT INTO t_ddb2 VALUES (1);
    ALTER TABLE t_ddb2 ADD COLUMN b int;
    ALTER TABLE t_ddb2 ADD COLUMN c int;
    ALTER TABLE t_ddb2 ADD COLUMN d int DEFAULT 100, ADD COLUMN e int DEFAULT 10;
    ALTER TABLE t_ddb2 RENAME COLUMN b TO f;
    ALTER TABLE t_ddb2 RENAME TO t_ddb4;
END;
$$;

SELECT * FROM f2();

DROP TABLE t_ddb4;

-- ...unless there's also PG only changes happing in the same transaction (no matter the order of statements).
BEGIN;
    CREATE TABLE t_x(a int);
    CREATE TEMP TABLE t_ddb2(a int) USING duckdb;
END;

BEGIN;
    CREATE TEMP TABLE t_ddb2(a int) USING duckdb;
    CREATE TABLE t_x(a int);
END;

BEGIN;
    CREATE TABLE t_x(a int);
    CREATE TEMP TABLE t_ddb2(a) USING duckdb AS SELECT 1;
END;

BEGIN;
    CREATE TEMP TABLE t_ddb2(a) USING duckdb AS SELECT 1;
    CREATE TABLE t_x(a int);
END;

-- And again the same for functions

CREATE OR REPLACE FUNCTION f2() RETURNS void
    LANGUAGE plpgsql
    RETURNS NULL ON NULL INPUT
    AS
$$
BEGIN
    CREATE TABLE t_x(a int);
    CREATE TEMP TABLE t_ddb2(a int) USING duckdb;
END;
$$;

SELECT * FROM f2();

CREATE OR REPLACE FUNCTION f2() RETURNS void
    LANGUAGE plpgsql
    RETURNS NULL ON NULL INPUT
    AS
$$
BEGIN
    CREATE TABLE t_x(a int);
    CREATE TEMP TABLE t_ddb2(a int) USING duckdb;
END;
$$;

SELECT * FROM f2();

BEGIN;
    CREATE TEMP TABLE t_ddb2(a) USING duckdb AS SELECT 1;
    CREATE TABLE t_x(a int);
    DROP TABLE t_ddb;
END;

BEGIN;
    DROP TABLE t_ddb;
    CREATE TABLE t_x(a int);
END;

BEGIN;
    CREATE TABLE t_x(a int);
    DROP TABLE t_ddb;
END;

BEGIN;
    CREATE TABLE t_x(a int);
    ALTER TABLE t_ddb ADD COLUMN b int;
END;

BEGIN;
    ALTER TABLE t_ddb ADD COLUMN b int;
    CREATE TABLE t_x(a int);
END;

BEGIN;
    CREATE TABLE t_x(a int);
    ALTER TABLE t_ddb RENAME COLUMN a TO z;
END;

BEGIN;
    ALTER TABLE t_ddb RENAME COLUMN a TO z;
    CREATE TABLE t_x(a int);
END;

BEGIN;
    CREATE TABLE t_x(a int);
    ALTER TABLE t_ddb RENAME TO t_ddb_new;
END;

BEGIN;
    ALTER TABLE t_ddb RENAME TO t_ddb_new;
    CREATE TABLE t_x(a int);
END;

-- Dropping both duckdb tables and postgres tables in the same command is
-- disallowed in a transaction.
BEGIN;
    DROP TABLE t, t_ddb;
END;

-- Dropping both duckdb tables and postgres tables in the same command is
-- disallowed in a transaction.
BEGIN;
    DROP TABLE t, t_ddb;
END;

-- In separate commands it's also not allowed
BEGIN;
    DROP TABLE t;
    DROP TABLE t_ddb;
END;

-- ...in any order
BEGIN;
    DROP TABLE t_ddb;
    DROP TABLE t;
END;

-- Non-existing tables should be allowed to be dropped in a transaction
-- together with DuckDB.
BEGIN;
    DROP TABLE IF EXISTS t_ddb, t_doesnotexist;
END;
CREATE TEMP TABLE t_ddb(a int) USING duckdb;


-- It should also not be allowed to drop duckdb and postgres tables in the same
-- transaction if it's implicitly done using a DROP SCHEMA ... CASCADE.
CREATE SCHEMA mixed;
CREATE TEMP TABLE t_ddb2(a int) USING duckdb;
-- Insert a row into pg_depend to make t_ddb depend on the mixed schema. We do
-- this because wo cannot insert TEMP tables in a schema. This is meant to
-- emulate a MotherDuck table in the mixed schema. To be clear, this is a
-- pretty big hack. Normally you're not supposed to manually mess with
-- pg_depend, but it's the easiest way to test this.
-- NOTE: 1259 is the oid for pg_class, and 2615 is the oid for pg_namespace. These
-- are not expected to change.
INSERT INTO pg_depend(classid, objid, objsubid, refclassid, refobjid, refobjsubid, deptype) SELECT 1259, 't_ddb2'::regclass, 0, 2615, 'mixed'::regnamespace, 0, 'n';
BEGIN;
    DROP SCHEMA mixed CASCADE;
END;

-- We have a special message for tables
CREATE TABLE mixed.t(a int);
BEGIN;
    DROP SCHEMA mixed CASCADE;
END;

-- It should work outside of a transaction though.
DROP SCHEMA mixed CASCADE;

TRUNCATE t_ddb;
INSERT INTO t_ddb VALUES (1);

BEGIN;
DECLARE c SCROLL CURSOR FOR SELECT a FROM t_ddb;
FETCH NEXT FROM c;
FETCH NEXT FROM c;
FETCH PRIOR FROM c;
COMMIT;

DROP FUNCTION f, f2;
DROP TABLE t;

BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
-- Will fail with does invalid snapshot identifier error (but not with
SET TRANSACTION SNAPSHOT 'abcd1234-5678-90ab-cdef-1234567890ab';
ROLLBACK;

CREATE TABLE foo AS SELECT 'bar'::text AS t;
BEGIN; SET duckdb.force_execution = true; SELECT t::integer AS t1 FROM foo; ROLLBACK;
SET duckdb.force_execution = true;
SELECT 1 FROM foo;

-- Make sure we query the cache during a valid TX
DROP EXTENSION IF EXISTS pg_duckdb CASCADE;

BEGIN;
CREATE EXTENSION pg_duckdb;
SELECT * FROM do_not_exist;
END;

CREATE EXTENSION pg_duckdb;

\set pwd `pwd`

CREATE TABLE t(a INT);
INSERT INTO t SELECT g from generate_series(1,10) g;
SELECT count(*) FROM t;
SELECT count(*) FROM public.t;

-- Create schema `other`
CREATE SCHEMA other;
CREATE TABLE other.t(a INT);
INSERT INTO other.t SELECT g from generate_series(1,100) g;
SELECT count(*) FROM other.t;

-- Test fully qualified table name combinations
SELECT count(*) FROM public.t, other.t;
SELECT count(*) FROM t, other.t;
SELECT count(*) FROM t,t;

-- search_path ORDER matters.
SET search_path TO other, public;
SELECT count(*) FROM t;
SELECT count(*) FROM t, public.t;

-- No search_path
SET search_path TO '';
SELECT count(*) FROM t, other.t;
SELECT count(*) FROM public.t, other.t;

SELECT count(*) FROM public.read_csv(:'pwd' || '/data/web_page.csv');

-- Cleanup
DROP TABLE other.t;
DROP SCHEMA other;
RESET search_path;

drop table t;

# Transactions in pg_duckdb

Multi-statement transactions are supported in pg_duckdb. There is one important restriction on this though, which is currently necessary to ensure the expected ACID guarantees: You cannot write to both a Postgres table and a DuckDB table in the same transaction.

Similarly you are allowed to do DDL (like `CREATE`/`DROP TABLE`) on DuckDB tables inside a transaction, but it's not allowed to combine such statements with DDL involving Postgres objects.

Finally it's possible to disable this restriction completely, and allow writes to both DuckDB and Postgres in the same transaction by setting `duckdb.unsafe_allow_mixed_transactions` to `true`. **This is at your own risk** and can result in the transaction being committed only in DuckDB, but not in Postgres. This can lead to inconsistencies and even data loss. For example the following code might result in deleting the `duckdb_table`, while not copying its contents to `pg_table`:

```sql
BEGIN;
SET LOCAL duckdb.unsafe_allow_mixed_transactions TO true;
CREATE TABLE pg_table AS SELECT * FROM duckdb_table;
DROP TABLE duckdb_table;
COMMIT;
```

-- XML is not supported, pushdown should avoid problems
CREATE TABLE my_table(a TEXT, b XML, c INTEGER);
INSERT INTO my_table (a, b, c) SELECT * from (
	VALUES
		('a', '<root><element>value</element></root>'::XML, 42),
		(NULL, NULL, NULL),
		('b', '<root><element>value</element></root>'::XML, -128),
		('c', '<root><element>value</element></root>'::XML, 2000000)
) t(a);
SELECT a, c FROM my_table;

CREATE TABLE t1(a INT, b INT, c TEXT);
INSERT INTO t1 SELECT g, g % 100, 'scan_potgres_table_'||g from generate_series(1,100000) g;

SET duckdb.log_pg_explain = true;

-- COUNT(*)
SELECT COUNT(*) FROM t1;

-- SEQ SCAN
SELECT COUNT(a) FROM t1 WHERE a < 10;

-- CREATE INDEX on t1
CREATE INDEX ON t1(a);

-- BITMAP INDEX
SELECT COUNT(a) FROM t1 WHERE a < 10;

-- INDEXONLYSCAN
SET enable_bitmapscan TO false;
SELECT COUNT(a) FROM t1 WHERE a = 1;

-- INDEXSCAN
SELECT COUNT(c) FROM t1 WHERE a = 1;

-- TEMPORARY TABLES JOIN WITH HEAP TABLES
CREATE TEMP TABLE t2(a int);
INSERT INTO t2 VALUES (1), (2), (3);

SELECT t1.a, t2.a FROM t1, t2 WHERE t1.a = t2.a;

-- JOIN WITH SAME TABLE (on WORKERS)
SELECT COUNT(*) FROM t1 AS t1_1, t1 AS t1_2 WHERE t1_1.a < 2 AND t1_2.a > 8;

-- JOIN WITH SAME TABLE (in BACKEND PROCESS)
SET max_parallel_workers TO 0;
SELECT COUNT(*) FROM t1 AS t1_1, t1 AS t1_2 WHERE t1_1.a < 2 AND t1_2.a > 8;
SET max_parallel_workers TO DEFAULT;


-- PARTITIONED TABLE

CREATE TABLE partitioned_table(a int, b INT, c text) PARTITION BY RANGE (a);
CREATE TABLE partition_1 PARTITION OF partitioned_table FOR VALUES FROM (0) TO (50);
CREATE TABLE partition_2 PARTITION OF partitioned_table FOR VALUES FROM (50) TO (100);
INSERT INTO partitioned_table SELECT g % 100, g, 'abcde_'||g from generate_series(1,100000) g;
CREATE INDEX ON partitioned_table(b);

SELECT COUNT(*) FROM partitioned_table WHERE a < 25;
SELECT COUNT(*) FROM partitioned_table WHERE a < 75;
SELECT COUNT(*) FROM partitioned_table WHERE a < 25 OR a > 75;
SELECT COUNT(*) FROM partitioned_table WHERE a < 25 AND b = 1;
SELECT COUNT(*) FROM partitioned_table, t2 WHERE partitioned_table.a = t2.a AND partitioned_table.a < 2;


SET enable_bitmapscan TO DEFAULT;
DROP TABLE t1, t2, partitioned_table;

-- Prepare source table
SET duckdb.force_execution = off;
CREATE TABLE tbl (id int, d float, c text);
INSERT INTO tbl SELECT i, 0.1, 'hello world' FROM generate_series(1, 1000000) i;

-- do CTAS using duckdb
SET duckdb.force_execution = on;
SET duckdb.max_workers_per_postgres_scan = 0;
SET duckdb.threads = 4;
CREATE TABLE tbl2 AS SELECT * FROM tbl;
SELECT count(*) FROM tbl2;

-- TODO: add case for INSERT INTO <dest> SELECT * FROM <src>

DROP TABLE tbl, tbl2;

CREATE TABLE tbl (id int, c float8, d text);
INSERT INTO tbl SELECT i, i * 2.0, 'helloworld' FROM generate_series(1, 1000000) i;
SELECT * FROM tbl ORDER BY 1,2,3 LIMIT 3;
DROP TABLE tbl;

-- JSON/LIST type
CREATE TABLE tbl (id int, c jsonb, d text[]);
INSERT INTO tbl SELECT i, jsonb_build_object('a', i), array_agg(i) FROM generate_series(1, 500000) i GROUP BY i;
SELECT * FROM tbl ORDER BY id DESC LIMIT 3;

CREATE TABLE tbl1 (id int, c jsonb, d text[]);
INSERT INTO tbl1 SELECT i, jsonb_build_object('a', i), array_agg(i) FROM generate_series(1, 100000) i GROUP BY i;
SELECT tbl.id, tbl.c, tbl.d, tbl1.c, tbl1.d FROM tbl JOIN tbl1 ON tbl.id = tbl1.id ORDER BY 1,2,3,4 LIMIT 5;

DROP TABLE tbl, tbl1;

-- case: SELECT * FROM READ_CSV
CREATE TABLE tbl (sepal_length float, variety varchar);
INSERT INTO tbl SELECT r['sepal.length']::float, r['variety']::varchar FROM read_csv('../../data/iris.csv') r;
SELECT sepal_length, variety FROM tbl ORDER BY sepal_length LIMIT 5;
DROP TABLE tbl;

-- case: SELECT * FROM READ_JSON
CREATE TABLE tbl (a int PRIMARY KEY, b varchar, c real);
INSERT INTO tbl SELECT r['a']::int, r['b']::varchar, r['c']::real FROM read_json('../../data/table.json') r;
SELECT * FROM tbl ORDER BY a LIMIT 5;
-- DO IT AGAIN TO VALIDATE PK CONSTRAINT
INSERT INTO tbl SELECT r['a']::int, r['b']::varchar, r['c']::real FROM read_json('../../data/table.json') r;
DROP TABLE tbl;

-- case: INSERT INTO PARTITION TABLE
CREATE TABLE tbl (a int PRIMARY KEY, b text) PARTITION BY RANGE (a);
CREATE TABLE tbl_p1 PARTITION OF tbl FOR VALUES FROM (1) TO (10);
CREATE TABLE tbl_p2 PARTITION OF tbl FOR VALUES FROM (10) TO (20);
INSERT INTO tbl select r['a']::int, r['b']::text from duckdb.query($$ SELECT 1 a, 'abc' b $$) r;
INSERT INTO tbl select r['a']::int, r['b']::text from duckdb.query($$ SELECT 11 a, 'def' b $$) r;
INSERT INTO tbl select r['a']::int, r['b']::text from duckdb.query($$ SELECT 21 a, 'ghi' b $$) r;
SELECT * FROM tbl_p1 ORDER BY a;
SELECT * FROM tbl_p2 ORDER BY a;
DROP TABLE tbl;

-- case: INSERT INTO TABLE (col1, col3)
CREATE TABLE tbl (a int PRIMARY KEY, b text, c int DEFAULT 10);
INSERT INTO tbl (a, c) SELECT i, 20 FROM generate_series(1, 3) i;
INSERT INTO tbl (a, b) SELECT i, 'foo' FROM generate_series(4, 6) i;
SELECT * FROM tbl;
DROP TABLE tbl;

-- case: INSERT INTO TABLE (col2, col1), i.e. columns in a different order
-- than the table definition
CREATE TABLE tbl (a int, b text, c int);
INSERT INTO tbl (b, a) SELECT r['x']::text, r['y']::int FROM duckdb.query($$ SELECT 'hello' x, 42 y $$) r;
INSERT INTO tbl (c, a, b) SELECT r['x']::int, r['y']::int, r['z']::text FROM duckdb.query($$ SELECT 1 x, 2 y, 'abc' z $$) r;
SELECT * FROM tbl ORDER BY a;
DROP TABLE tbl;

-- case: table with a dropped column
CREATE TABLE tbl (a int, b text, c int);
ALTER TABLE tbl DROP COLUMN b;
INSERT INTO tbl (c, a) SELECT r['x']::int, r['y']::int FROM duckdb.query($$ SELECT 1 x, 2 y $$) r;
SELECT * FROM tbl;
DROP TABLE tbl;

-- case: values that don't fit the column type throw an error, just like
-- they would with Postgres execution
CREATE TABLE tbl (v varchar(3));
INSERT INTO tbl SELECT r['s']::text FROM duckdb.query($$ SELECT 'abcdef' s $$) r;
SELECT * FROM tbl;
DROP TABLE tbl;

-- case: GENERATED and default columns are computed for rows produced by DuckDB
CREATE TABLE tbl (a int, b int GENERATED ALWAYS AS (a * 2) STORED, c serial);
INSERT INTO tbl (a) SELECT r['a']::int FROM duckdb.query($$ SELECT 21 a UNION ALL SELECT 33 $$) r;
SELECT * FROM tbl ORDER BY a;
DROP TABLE tbl;

-- case: prepared statements with parameters
CREATE TABLE tbl (a int, b text);
PREPARE heap_insert(int) AS INSERT INTO tbl SELECT r['a']::int, r['b']::text FROM duckdb.query($$ SELECT 1 a, 'foo' b UNION ALL SELECT 2, 'bar' $$) r WHERE r['a']::int = $1;
EXECUTE heap_insert(1);
EXECUTE heap_insert(2);
EXECUTE heap_insert(2);
SELECT * FROM tbl ORDER BY a;
DEALLOCATE heap_insert;
DROP TABLE tbl;

-- case: CTEs attached to the INSERT are moved into the SELECT that DuckDB
-- executes
CREATE TABLE tbl (a int, b text);
WITH x AS (SELECT r['a']::int a, r['b']::text b FROM duckdb.query($$ SELECT 1 a, 'basic' b $$) r)
INSERT INTO tbl SELECT * FROM x;
-- Also when they reference each other, are recursive, or when the SELECT has
-- CTEs of its own
WITH x AS (SELECT r['a']::int a FROM duckdb.query($$ SELECT 2 a $$) r),
     y AS (SELECT a, 'chained' FROM x)
INSERT INTO tbl SELECT * FROM y;
WITH RECURSIVE fib(a, b) AS (
    SELECT 3, 'rec' UNION ALL SELECT a + 1, b FROM fib WHERE a < 5
)
INSERT INTO tbl SELECT a, b FROM fib, duckdb.query($$ SELECT 1 $$) r;
WITH x AS (SELECT r['a']::int a FROM duckdb.query($$ SELECT 6 a $$) r)
INSERT INTO tbl WITH y AS (SELECT a, 'both' FROM x) SELECT * FROM y;
-- CTEs inside the SELECT itself also work on their own
INSERT INTO tbl SELECT * FROM (WITH x AS (SELECT r['a']::int a, r['b']::text b FROM duckdb.query($$ SELECT 7 a, 'sub' b $$) r) SELECT * FROM x) sub;
-- A CTE that shadows a real table reads from the CTE, not the table
CREATE TABLE x (a int, b text);
INSERT INTO x VALUES (99, 'WRONG');
WITH x AS (SELECT r['a']::int a, 'shadow'::text b FROM duckdb.query($$ SELECT 8 a $$) r)
INSERT INTO tbl SELECT * FROM x;
-- If the same CTE name is used on both the INSERT and the SELECT, DuckDB
-- errors on the duplicate name instead of silently picking one
WITH x AS (SELECT r['a']::int a, 'outer'::text b FROM duckdb.query($$ SELECT 9 a $$) r)
INSERT INTO tbl WITH x AS (SELECT 9, 'inner') SELECT * FROM x;
SELECT * FROM tbl ORDER BY a;
DROP TABLE tbl, x;

-- case: EXPLAIN ANALYZE is not supported, because it would silently insert
-- nothing while a Postgres-executed EXPLAIN ANALYZE actually inserts the rows
CREATE TABLE tbl (a int);
EXPLAIN (ANALYZE, COSTS OFF) INSERT INTO tbl SELECT r['a']::int FROM duckdb.query($$ SELECT 1 a $$) r;
SELECT * FROM tbl;
DROP TABLE tbl;

-- case: RETURNING
CREATE TABLE tbl (a int PRIMARY KEY, b text);
INSERT INTO tbl (a, b) SELECT i, 'foo' FROM generate_series(1, 3) i RETURNING a, b;
DROP TABLE tbl;

-- case: ON CONFLICT DO UPDATE
CREATE TABLE tbl (a int PRIMARY KEY, b text);
INSERT INTO tbl SELECT i, 'foo' FROM generate_series(1, 3) i;
INSERT INTO tbl (a, b) SELECT i, 'qux' FROM generate_series(1, 3) i ON CONFLICT (a) DO UPDATE SET b = 'qux';
SELECT * FROM tbl;
DROP TABLE tbl;

-- case: ON CONFLICT DO NOTHING
CREATE TABLE tbl (a int PRIMARY KEY, b text);
INSERT INTO tbl (a, b) SELECT i, 'foo' FROM generate_series(1, 2) i;
INSERT INTO tbl (a, b) SELECT i, 'qux' FROM generate_series(1, 4) i ON CONFLICT DO NOTHING;
SELECT * FROM tbl;
DROP TABLE tbl;

CREATE TABLE tbl (a INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, b text);
INSERT INTO tbl (b) SELECT 'foo' FROM generate_series(1, 2);
INSERT INTO tbl (b) SELECT 'qux' FROM generate_series(1, 4);;
SELECT * FROM tbl;
DROP TABLE tbl;

CREATE TABLE tbl (a SERIAL PRIMARY KEY, b text);
INSERT INTO tbl (b) SELECT 'foo' FROM generate_series(1, 2);
INSERT INTO tbl (b) SELECT 'qux' FROM generate_series(1, 4);;
SELECT * FROM tbl;
DROP TABLE tbl;

-- case: ARRAY / JSON type
CREATE TABLE tbl (a int, b text[], c jsonb);
CREATE TABLE tbl1 (a int, b text[], c jsonb);
INSERT INTO tbl (a, b, c) VALUES (1, ARRAY ['foo', 'bar'], '{"a": 1, "b": 2}');
INSERT INTO tbl1 SELECT * FROM tbl;
SELECT * FROM tbl1;
DROP TABLE tbl, tbl1;

-- case: UPDATE/DELETE and INSERT ... VALUES fall back to Postgres execution
CREATE TABLE tbl (a int PRIMARY KEY, b text);
INSERT INTO tbl (a, b) SELECT i, 'foo' FROM generate_series(1, 3) i;
UPDATE tbl SET b = 'bar' WHERE a = 1;
DELETE FROM tbl WHERE a = 2;
INSERT INTO tbl (a, b) VALUES (4, 'baz');
SELECT * FROM tbl ORDER BY a;
-- But when such statements require DuckDB execution, falling back to Postgres
-- is not possible, so they throw an error instead.
UPDATE tbl SET b = r['x']::text FROM duckdb.query($$ SELECT 'bar' x $$) r WHERE a = 1;
DELETE FROM tbl USING duckdb.query($$ SELECT 1 x $$) r WHERE a = r['x']::int;
INSERT INTO tbl VALUES (5, (SELECT r['x']::text FROM duckdb.query($$ SELECT 'quux' x $$) r));
DROP TABLE tbl;

-- case: UNSUPPORTED TYPE
CREATE TABLE tbl (a int, b xml);
CREATE TABLE tbl1 (a int, b xml);
INSERT INTO tbl (a, b) VALUES (1, '<xml>foo</xml>');
-- This falls back to Postgres execution, because DuckDB doesn't support the
-- xml type.
INSERT INTO tbl1 SELECT * FROM tbl;
SELECT * FROM tbl1;
-- When DuckDB execution is required we throw an error instead.
INSERT INTO tbl1 SELECT r['a']::int, NULL FROM duckdb.query($$ SELECT 1 a $$) r;
DROP TABLE tbl, tbl1;

-- case: query with JOIN
CREATE TABLE tbl (a int, b text);
CREATE TABLE tbl1 (a int, b1 text, b2 text);
INSERT INTO tbl (a, b) VALUES (1, 'foo'), (2, 'bar'), (1, 'baz');
-- We don't EXPLAIN this INSERT, because the DuckDB plan that would be
-- included in the output is different for Debug and Release builds of DuckDB.
INSERT INTO tbl1 SELECT a.a, a.b, b.b FROM tbl a JOIN tbl b ON a.a = b.a;
SET duckdb.log_pg_explain to on;
-- A query with a VALUES RTE in the subquery falls back to Postgres execution
INSERT INTO tbl1 SELECT a.a, a.b, b.column2 FROM tbl a JOIN (VALUES (2, 'yoyo'), (4, 'yoyo2')) AS b(column1, column2) ON a.a = b.column1;
SELECT * FROM tbl1 ORDER BY 1, 2, 3;
SET duckdb.log_pg_explain to off;
-- But when DuckDB execution is required, the VALUES RTE is accepted and the
-- whole SELECT runs in DuckDB.
INSERT INTO tbl1 SELECT r['a']::int, r['b']::text, b.column2 FROM duckdb.query($$ SELECT 2 a, 'x' b $$) r JOIN (VALUES (2, 'yoyo')) AS b(column1, column2) ON r['a']::int = b.column1;
SELECT * FROM tbl1 WHERE b1 = 'x';
DROP TABLE tbl, tbl1;

-- INT4 (zero dimension)
CREATE TABLE int_array_0d(a INT[]);
INSERT INTO int_array_0d SELECT CAST(a as INT[]) FROM (VALUES
    ('{}')
) t(a);
SELECT * FROM int_array_0d;

-- INT4 (single dimension)
CREATE TABLE int_array_1d(a INT[]);
INSERT INTO int_array_1d SELECT CAST(a as INT[]) FROM (VALUES
    ('{1, 2, 3}'),
